snippets.snippet:
specification {
  element person
  element system
  element container
}

model {
  user = person "User"

  mySystem = system "My System" {
    webapp = container "Web Application" "Handles UI and upload flow"
    api = container "API Service"
    db = container "Database"
  }

  emailSvc = system "External Email Service"

  user -> mySystem.webapp "Uses"
  mySystem.webapp -> mySystem.api "Calls"
  mySystem.api -> mySystem.db "Reads/Writes"
  mySystem.api -> emailSvc "Sends notifications"
}

views {
  view landscape of mySystem {
    include user
    include mySystem
    include emailSvc
    title "System Landscape"
  }

  view containers of mySystem {
    include *
    include user
    include emailSvc
    title "C2 - Containers"
    description "Container view with drill-down anchored on Web Application"
  }

  view webapp_drilldown of mySystem.webapp {
    include *
    title "Web Application Drill-down"
  }
}

model {
  user = person "User"

  systemA = system "Platform" {
    web = container "Web App"
    api = container "API"
    db = container "PostgreSQL"
  }

  extMail = system "External Email Service"

  user -> systemA.web "Uses"
  systemA.api -> extMail "Sends email"
}

deployment {
  environment prod {
    node internet "Internet" {
      instance user
    }

    node dmz "DMZ" {
      node lb "Load Balancer"
      instance systemA.web
    }

    node app_tier "App Tier" {
      node app_cluster "Kubernetes Cluster" {
        instance systemA.api
      }
    }

    node data_tier "Data Tier" {
      node db_host "DB Host" {
        instance systemA.db
      }
    }

    node external "External Services" {
      instance extMail
    }
  }
}

views {
  deployment view prod_infra {
    title "Production Infrastructure - DMZ / App / Data"
    include prod.*
  }
}

model {
  user = person "User"

  platform = system "Platform" {
    web = container "Web App"
    uploadApi = container "Upload API"
    storage = container "Object Storage"
    scanner = container "Malware Scanner"
    notifier = container "Notification Service"
  }

  user -> platform.web "Uploads file"
  platform.web -> platform.uploadApi "POST /upload"
  platform.uploadApi -> platform.storage "Store blob" #critical
  platform.uploadApi -> platform.scanner "Scan file" #critical
  platform.uploadApi -> platform.notifier "Emit upload event"
}

views {
  dynamic view upload_journey {
    title "Upload Journey"

    user -> platform.web "1. Select and submit file"
    platform.web -> platform.uploadApi "2. Send upload request"
    platform.uploadApi -> platform.storage "3. Persist file"
    platform.uploadApi -> platform.scanner "4. Run security scan"
    platform.uploadApi -> platform.notifier "5. Publish completion event"
    platform.web -> user "6. Show success/failure"
  }
}

styles {
  element.tag "critical" {
    color red
  }
  relationship.tag "critical" {
    color red
  }
}

model {
  platform = system "Platform" {
    secGateway = container "Security Access Gateway"
    secSvcA = container "Dedicated Security Service A"
    secSvcB = container "Dedicated Security Service B"
  }

  secGateway -> secSvcA "Routes secured traffic"
  secGateway -> secSvcB "Routes secured traffic"
}

deployment {
  environment prod {
    node seczone "SecZone" {
      node bastion "Bastion"
      node firewall "Firewall"
      node secure_apps "Secure Services Cluster" {
        instance platform.secGateway
        instance platform.secSvcA
        instance platform.secSvcB
      }
    }
  }
}

views {
  view c2_seczone of platform {
    include platform.*
    title "C2 - SecZone Services"
  }

  deployment view deploy_prod_seczone {
    include prod.seczone.*
    title "Production Deployment - SecZone"
  }
}

views {
  view index {
    title 'System Landscape'

    include *

    autoLayout TopBottom
  }
}

views {
  view mySystem_containers of mySystem {
    title 'MySystem – Container View'

    include mySystem, mySystem.*

    autoLayout LeftRight
  }
}

views {
  view mySystem_containers of mySystem {
    title 'MySystem – Containers with External Users'

    include mySystem.*
    include element.tag == #Actor -> mySystem.*
    include mySystem.* -> element.tag == #System_External

    autoLayout TopBottom
  }
}

views {
  view cloud_services {
    title 'Cloud Services'
    description 'Elements tagged #Cloud'

    include element.tag == #Cloud

    autoLayout LeftRight
  }
}

views {
  view external_services {
    title 'External Cloud & SaaS'

    include element.tag == #Cloud
    include element.tag == #Saas
    include element.tag == #External

    autoLayout TopBottom
  }
}

views {
  view cloud_containers {
    title 'Cloud Containers'

    include element.tag == #Cloud and element.tag == #Container

    autoLayout TopBottom
  }
}

views {
  view myContainer_components of mySystem.myContainer {
    title 'MyContainer – Component View'

    include mySystem.myContainer.*

    autoLayout TopBottom
  }
}

views {
  view myContainer_components of mySystem.myContainer {
    title 'MyContainer – Components with Roles'

    include mySystem.myContainer.*

    style mySystem.myContainer.controller {
      color blue
    }

    style mySystem.myContainer.validator {
      color green
    }

    style mySystem.myContainer.repository {
      color amber
    }

    autoLayout LeftRight
  }
}

views {
  view system_landscape {
    title 'System Landscape'
    description 'All actors and systems at context level'

    include *

    autoLayout TopBottom
  }
}

views {
  view context_explicit {
    title 'Context – Explicit'

    include element.tag == #Actor
    include element.tag == #System

    autoLayout LeftRight
  }
}

views {
  view containers_mySystem of mySystem {
    title 'MySystem – Container Detail'
    description 'Shows all application containers within MySystem'

    include mySystem.*

    autoLayout LeftRight
  }
}

views {
  view containers_mySystem of mySystem {
    title 'MySystem – Full Data Flows'

    include mySystem.*

    // Show what calls the API container from outside
    include * -> mySystem.api

    // Show what the queue consumers write to
    include mySystem.consumer -> *

    autoLayout LeftRight
  }
}

views {
  view cloud_landscape {
    title 'Cloud-Hosted Components'

    include element.tag == #Cloud

    autoLayout TopBottom
  }
}

views {
  view prod_cloud {
    title 'Production Cloud Services'

    include element.tag == #Cloud and element.tag == #Production

    autoLayout LeftRight
  }
}

views {
  view cloud_with_context {
    title 'Cloud Services with Dependencies'

    include element.tag == #Cloud
    include element.tag == #Cloud -> *    // what cloud elements call
    include * -> element.tag == #Cloud    // what calls into cloud elements

    autoLayout TopBottom
  }
}

views {
  view detail_myContainer of mySystem.myContainer {
    title 'MyContainer – Component Detail'
    description 'Shows the internal components of MyContainer'

    include mySystem.myContainer.*

    autoLayout LeftRight
  }
}

views {
  view detail_myContainer of mySystem.myContainer {
    title 'MyContainer – Deep Components'

    include mySystem.myContainer.**   // all descendants recursively

    autoLayout TopBottom
  }
}

myContainer = Container_Api 'My Container' {
  link detail_myContainer
}

style mySystem.myContainer.authService {
  color red  // highlight security-critical component
}
